with kept_keys as (select id, product_id from store_sales except select id, product_id from store_sales where store_id in (3, 6)), reconciled as (select s.* from store_sales s inner join kept_keys k on s.id = k.id and s.product_id = k.product_id) select case when units >= 40 then 'PREMIUM' else 'STANDARD' end as units_tier, case when revenue >= 4300 then 'LARGE' else 'SMALL' end as revenue_tier, approx_percentile(revenue, array(0.25, 0.5, 0.75)) as revenue_quartiles, round(avg(revenue), 2) as avg_revenue, percentile_approx(units, array(0.25, 0.5, 0.75)) as units_quartiles, min(revenue) as min_revenue, count(distinct id) as distinct_ids, stddev_samp(units) as units_stddev, grouping_id() as grouping_id from reconciled group by grouping sets ((case when units >= 40 then 'PREMIUM' else 'STANDARD' end, case when revenue >= 4300 then 'LARGE' else 'SMALL' end), (case when units >= 40 then 'PREMIUM' else 'STANDARD' end));
